import {esc,icon} from './ui.js';
const when=value=>{const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-GH',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Accra'}).format(d):'';};
export async function openSupportNotifications(ctx,inbox,{caseId=null,notificationId=null}={}){
 const identity=()=>ctx.connected===true&&ctx.shared?.signedIn&&ctx.shared?.user?.id&&ctx.shared.recoveryScope!==null?JSON.stringify([ctx.shared.user.id,ctx.shared.authVersion??0,ctx.shared.recoveryScope]):'',actor=identity(),same=()=>identity()===actor;
 await inbox.refresh();if(!same())return;
 let release=null;
 function dispose(){release?.();release=null;}
 function current(el){if(el.isConnected===false)return false;if(same())return true;el.innerHTML='';dispose();ctx.closeSheet?.();return false;}
 function list(){if(!same())return;dispose();const data=inbox.snapshot;ctx.sheet(`<div class="support-updates"><span class="eyebrow">From Lumo support</span><h2>Support updates${data.unreadCount?` <span class="support-unread-count">${data.unreadCount}</span>`:''}</h2><p class="muted">Updates on the cases you have raised with us.</p>${data.error?`<p role="status" class="error">${esc(data.error)}</p>`:''}<div class="support-update-list">${data.notifications.map(n=>`<button class="support-update ${n.readAt?'':'unread'}" data-support-case="${esc(n.caseId)}" data-support-notice="${esc(n.id)}"><span class="support-update-top"><strong>${esc(n.title)}</strong>${n.readAt?'':'<span class="support-unread-dot" aria-label="Unread"></span>'}</span><span class="support-update-ref">${esc(n.reference)} · ${esc(n.statusLabel)}</span><span>${esc(n.body)}</span><small>${esc(when(n.createdAt))}</small></button>`).join('')||`<div class="support-updates-empty">${icon('chat',32)}<h3>${inbox.signedIn?'No support updates yet.':'Sign in for your support updates.'}</h3><p class="muted">Case status changes and messages from support will appear here.</p></div>`}</div>${data.notifications.length<data.total?'<button class="button secondary" data-support-more>Older updates</button>':''}<button class="button secondary" data-support-refresh>Refresh updates</button></div>`,el=>{
 el.querySelectorAll('[data-support-case]').forEach(b=>b.onclick=async()=>{b.disabled=true;dispose();const result=await inbox.readCase(b.dataset.supportCase,b.dataset.supportNotice);if(!current(el))return;if(result?.ok)detail(result.case);else{ctx.toast(result?.message||'This case could not open. Try again.');list();}});
 el.querySelector('[data-support-refresh]').onclick=async()=>{await inbox.refresh();if(current(el))list();};
 const more=el.querySelector('[data-support-more]');if(more)more.onclick=async()=>{await inbox.refresh(data.page+1);if(current(el))list();};
 release=inbox.subscribe(()=>{if(!current(el)){dispose();return;}if(!inbox.snapshot.loading)list();});
 },{onDispose:dispose});}
 function detail(c){if(!same())return;dispose();const report=c.source?.type==='consumer_support'?(ctx.state?.account?.supportCases||[]).find(item=>item.id===c.source.id):null;ctx.sheet(`<div class="support-updates"><span class="eyebrow">Lumo support case</span><h2>${esc(c.reference)}</h2>${c.sourceReference?`<p class="muted">Your app report: ${esc(c.sourceReference)}</p>`:''}<p class="support-case-status">${esc(c.statusLabel)}</p><div class="support-update-list">${(c.updates||[]).map(n=>`<article class="support-update"><strong>${esc(n.statusLabel)}</strong><p>${esc(n.body)}</p><small>${esc(when(n.createdAt))}</small></article>`).join('')}</div>${report?'<button class="button" data-support-reply>Reply to Lumo</button>':''}<button class="button secondary" data-support-back>All support updates</button><button class="button text" data-support-case-refresh>Refresh case</button></div>`,el=>{const reply=el.querySelector('[data-support-reply]');if(report&&reply)reply.onclick=()=>{if(!current(el))return;ctx.closeSheet?.();ctx.go({section:'life',page:'account-support-detail',id:report.id,supportReference:c.reference,returnTo:{section:'life',page:'account-support'}});};el.querySelector('[data-support-back]').onclick=list;el.querySelector('[data-support-case-refresh]').onclick=async()=>{const result=await inbox.readCase(c.id);if(current(el)&&result?.ok)detail(result.case);};});}
 if(caseId){const result=await inbox.readCase(caseId,notificationId);if(!same())return;if(result?.ok){detail(result.case);return;}ctx.toast(result?.message||'This case could not open. Try again.');}
 list();
}
